import java.io.*;

// Implements AutoCloseable interface
class Box implements AutoCloseable {
    public void close() {
        System.out.println("Box closed!");
    }
}

public class Main {
    public static void main(String[] args) {
        // Declare resource inside try (...) parentheses
        try (Box box = new Box()) {
            System.out.println("Using Box...");
            throw new RuntimeException("Boom!");
        } catch (Exception e) {
            System.out.println("Caught: " + e.getMessage());
        }
    }
}
